#!/usr/bin/env node
// Made with my soul - Swately <3
/*
 * Figure colour contract builder and gate. Zero dependencies.
 *
 *   node build-contract.mjs            regenerate phyriad-figure-colors.sty and theme-map.json
 *   node build-contract.mjs --roles f  use another palette file (tests)
 *   node build-contract.mjs --check    fail if either generated file is stale, or if any pair of roles
 *                                      misses its contrast target in either theme (the testbench side)
 *
 * Reads figure-roles.json, the single source. See README.md for how a project uses the output.
 */
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const BS = String.fromCharCode(92); // a backslash, written once so no shell or editor can eat it
const check = process.argv.includes('--check');

// --roles <file> reads another palette (the gate's own test uses it to prove the contrast check can fail)
const rolesArg = process.argv.indexOf('--roles');
const rolesPath = rolesArg > -1 ? process.argv[rolesArg + 1] : join(here, 'figure-roles.json');
const roles = JSON.parse(readFileSync(rolesPath, 'utf8'));

// ---- colour maths ---------------------------------------------------------------------------
const rgb = (h) => {
  const n = parseInt(h.slice(1), 16);
  return [n >> 16, (n >> 8) & 255, n & 255];
};
const hex = (c) => '#' + c.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('');
const mix = (a, b, t) => {
  const A = rgb(a);
  const B = rgb(b);
  return hex(A.map((v, i) => v * t + B[i] * (1 - t)));
};
const lin = (v) => {
  v /= 255;
  return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
};
const lum = (h) => {
  const [r, g, b] = rgb(h);
  return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
};
const contrast = (a, b) => {
  const [x, y] = [lum(a), lum(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
};

// ---- the full palette per theme: base roles plus the three derived tints ----------------------
const THEMES = ['light', 'dark'];
const palette = {};
for (const t of THEMES) {
  const r = roles[t];
  palette[t] = {
    ...r,
    fillAccent: mix(r.accent, r.paper, roles.tint[t]),
    fillOk: mix(r.ok, r.paper, roles.tint[t]),
    fillError: mix(r.error, r.paper, roles.tint[t]),
  };
}

// LaTeX names: fig + role. ink is TeX's default black and is deliberately NOT defined.
const NAMES = {
  paper: 'figPaper',
  muted: 'figMuted',
  accent: 'figAccent',
  ok: 'figOk',
  error: 'figError',
  fill: 'figFill',
  fillAccent: 'figFillAccent',
  fillOk: 'figFillOk',
  fillError: 'figFillError',
  border: 'figBorder',
};

// ---- generated file 1: the LaTeX colour file (light theme hexes) ---------------------------------
const sty = [
  '% GENERATED by figure-contract/build-contract.mjs from figure-roles.json. DO NOT EDIT.',
  '% Colours a project figure may use. Light-theme hexes; the site maps them to its dark theme.',
  '% Ink is TeX default black: never set it. Use ONE accent against muted ink; fills are tints.',
  BS + 'NeedsTeXFormat{LaTeX2e}',
  BS + 'ProvidesPackage{phyriad-figure-colors}[2026/10/10 site figure colour roles]',
  BS + 'RequirePackage{xcolor}',
  ...Object.entries(NAMES).map(
    ([role, name]) =>
      BS + 'definecolor{' + name + '}{HTML}{' + palette.light[role].slice(1).toUpperCase() + '}',
  ),
  '% Made with my soul - Swately <3',
  '',
].join('\n');

// ---- generated file 2: the map the site's theming step turns into one dark @media block ---------------
const entries = [];
// ink: TeX default black. dvisvgm leaves default text with NO fill attribute and writes strokes as #000.
entries.push({ role: 'ink', light: '#000000', dark: palette.dark.ink });
for (const [role] of Object.entries(NAMES)) {
  entries.push({ role, light: palette.light[role], dark: palette.dark[role] });
}
const rules = [];
rules.push('svg{fill:' + palette.dark.ink + '}');
rules.push('[stroke="#000"]{stroke:' + palette.dark.ink + '}');
rules.push('[fill="#000"]{fill:' + palette.dark.ink + '}');
for (const e of entries) {
  if (e.role === 'ink') continue;
  rules.push('[fill="' + e.light + '"]{fill:' + e.dark + '}');
  rules.push('[stroke="' + e.light + '"]{stroke:' + e.dark + '}');
}
const themeMap = {
  _why: 'GENERATED by figure-contract/build-contract.mjs from figure-roles.json. DO NOT EDIT. dvisvgm writes hex in lower case; match case-insensitively if you transform the file yourself.',
  version: 1,
  paper: { light: palette.light.paper, dark: palette.dark.paper },
  entries,
  darkBlock: '@media (prefers-color-scheme:dark){' + rules.join('') + '}',
};
const mapText = JSON.stringify(themeMap, null, 2) + '\n';

// ---- the contrast gate ---------------------------------------------------------------------------------
const failures = [];
const need = (label, a, b, min) => {
  const c = contrast(a, b);
  if (c < min) failures.push(label + ' ' + c.toFixed(2) + ' < ' + min);
};
for (const t of THEMES) {
  const p = palette[t];
  const surfaces = {
    paper: p.paper,
    fill: p.fill,
    fillAccent: p.fillAccent,
    fillOk: p.fillOk,
    fillError: p.fillError,
  };
  for (const [sn, sv] of Object.entries(surfaces)) need(t + ': ink on ' + sn, p.ink, sv, 4.5);
  for (const sn of ['paper', 'fill']) need(t + ': muted on ' + sn, p.muted, surfaces[sn], 4.5);
  for (const [role, own] of [
    ['accent', 'fillAccent'],
    ['ok', 'fillOk'],
    ['error', 'fillError'],
  ]) {
    for (const sn of ['paper', 'fill', own])
      need(t + ': ' + role + ' text on ' + sn, p[role], surfaces[sn], 4.5);
  }
  // lines and arrows are graphical objects: 3:1 against the paper (WCAG 1.4.11)
  for (const role of ['ink', 'muted', 'accent', 'ok', 'error'])
    need(t + ': ' + role + ' line on paper', p[role], p.paper, 3);
}

if (check) {
  const stale = [];
  const read = (f) => (existsSync(join(here, f)) ? readFileSync(join(here, f), 'utf8') : '');
  if (read('phyriad-figure-colors.sty') !== sty) stale.push('phyriad-figure-colors.sty');
  if (read('theme-map.json') !== mapText) stale.push('theme-map.json');
  for (const s of stale) console.log('  STALE  ' + s + ' (run: node build-contract.mjs)');
  for (const f of failures) console.log('  FAIL   ' + f);
  const ok = stale.length === 0 && failures.length === 0;
  console.log(
    ok
      ? 'PASS: generated files current, every role pair meets its contrast target in both themes'
      : 'FAIL',
  );
  process.exit(ok ? 0 : 1);
}
if (failures.length) {
  for (const f of failures) console.log('  FAIL   ' + f);
  console.log('Not writing: the palette misses a contrast target.');
  process.exit(1);
}
writeFileSync(join(here, 'phyriad-figure-colors.sty'), sty);
writeFileSync(join(here, 'theme-map.json'), mapText);
console.log('wrote phyriad-figure-colors.sty and theme-map.json');
